"""Check every quantitative statement of the revised manuscript against the result files.

Each check recomputes a number (or a range, ordering or count) from revision/outputs/*.json
(or from the cached data) and asserts that (i) the claim holds and (ii) the exact string
used in the manuscript is present in Main.tex. Table bodies are checked separately by
comparing them with the snippets generated by figures/paper_tables.py.

usage: python revision/experiments/check_manuscript_numbers.py /path/to/Main.tex
"""
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
import numpy as np
import pvs_eval as E

TEX = open(sys.argv[1]).read()
O = E.OUT_DIR
load = lambda n: json.load(open(O / n))
grid, fl, pst, base, bl, sw = (load("main_grid.json"), load("frame_level_vs.json"), load("paired_stats.json"),
                               load("baselines_loeo.json"), load("baselines.json"), load("param_sweep_summary.json"))
pg = load("param_grid.json")
ab, tu, rq, sp, ds, rt = (load("absent_targets.json"), load("target_update_check.json"), load("reel_quality.json"),
                          load("sparse_sampling.json"), load("dataset_stats.json"), load("runtime_summary.json"))
failures, n = [], 0
P = lambda x, d=1: f"{100 * x:.{d}f}"


def check(name, cond, *fragments):
    global n
    n += 1
    missing = [f for f in fragments if f not in TEX]
    if not cond or missing:
        failures.append((name, cond, missing))
        print(f"FAIL {name}: cond={cond} missing={missing}")


F = lambda src, k: grid[src][k]["overall"][2]
ci = lambda src, k: grid[src][k]["overall_F_ci95"]
best = "transface|SEQ|upd"

# ---------- headline numbers (abstract, highlights, results, conclusion)
check("best F", P(F("QD-DETR", best)) == "69.8" and max(grid["QD-DETR"], key=lambda k: F("QD-DETR", k)) == best, "a 69.8\\% event-level F-score, and a zero-shot summarizer comes within 1.4 points (68.4\\%)", "F-score of 69.8\\% (95\\% CI 65.2--74.5)", "ID~14, $69.8\\%$ overall F-score, 95\\% CI $[65.2, 74.5]$")
check("best CI", [P(c) for c in ci("QD-DETR", best)] == ["65.2", "74.5"], "F-score of 69.8\\% (95\\% CI 65.2--74.5)")
check("zero-shot best", P(F("SportCLIP", best)) == "68.4" and max(grid["SportCLIP"], key=lambda k: F("SportCLIP", k)) == best, "(68.4\\%)", "ID~6, $68.4\\%$, CI $[62.9, 73.7]$")
check("zero-shot CI", [P(c) for c in ci("SportCLIP", best)] == ["62.9", "73.7"])
check("highlight", P(F("SportCLIP", best)) == "68.4" and P(F("QD-DETR", best)) == "69.8", "Zero-shot summarizer on par with a supervised one: 68.4\\% vs.\\ 69.8\\% event F-score")
check("in-sample", P(F("QD-DETR-insample", best)) == "72.9" and P(F("QD-DETR-insample", best) - F("QD-DETR", best)) == "3.1", "by 3.1 points (72.9\\% instead of 69.8\\%)", "A model trained on all 20 broadcasts")

# ---------- dataset
S = ds["summary"]
check("videos/events", S["videos"] == 20 and S["events"] == 938, "The 938 highlight events are performed by 186 athlete--video instances")
check("athlete-video pairs", S["athlete_video_pairs"] == 186)
check("athletes per video", S["athletes_per_video"] == [5, 9.5, 13], "5 to 13 athletes per video")
check("events per athlete", S["events_per_athlete_video"] == [1, 4.0, 15], "1 to 15 events per athlete and video, median 4")
check("distinct athletes", S["unique_athletes"] == 137 and S["recurring_athletes"] == 36 and S["max_videos_per_athlete"] == 4, "i.e., 137 distinct athletes, 36 of whom compete in more than one broadcast")
check("championships", S["competitions"] == 9 and min(S["years"]) == 2015 and max(S["years"]) == 2025, "nine World and European championships (2015--2025)")
check("women/indoor", S["women_finals"] == 4 and S["indoor"] == 5)  # Table 1 (Sex, Venue and Total row)
durs = [v["duration_s"] / 60 for v in ds["videos"]]
check("durations", f"{min(durs):.1f}" == "18.5" and f"{max(durs):.1f}" == "47.2" and f"{S['total_hours']:.1f}" == "10.2")  # Table 1 (durations and Total row)
fps = [round(v["fps"], 3) for v in ds["videos"]]
check("frame rates", fps.count(25.0) == 15 and fps.count(50.0) == 4 and fps.count(23.976) == 1)  # per-video frame rates: Table 1
check("Oregon", sum("Oregon 2022" in v["competition"] for v in ds["videos"]) == 5)  # no longer quoted in the text
check("UN bands", max(S["un_band_frames_before"], key=S["un_band_frames_before"].get) == "15" and list(S["un_band_frames_after"]) == ["30"], "the 15 frames before and the 30 frames after each HL interval", "(0.6\\,s and 1.2\\,s at 25\\,fps)")
check("total duration table", f"{sum(durs):.1f}" == "612.5", "& 612.5 & 186 & 938 &")
# face-bearing frame coverage
cov = []
for v in E.VIDEOS:
    fr = np.load(f"/mnt/Data/mrt/PVS_revision_cache/{v}_transface.npz")["frame"]
    cov.append(len(np.unique(fr)) / E.video_meta(v)["nb_frames"])
check("face-bearing coverage", (round(100 * min(cov)), round(100 * max(cov))) == (45, 79), "(45--79\\% of the frames of each video)")
faces = [len(np.load(f"/mnt/Data/mrt/PVS_revision_cache/{v}_transface.npz")["frame"]) / E.video_meta(v)["nb_frames"] for v in E.VIDEOS]
tot = sum(len(np.load(f"/mnt/Data/mrt/PVS_revision_cache/{v}_transface.npz")["frame"]) for v in E.VIDEOS) / sum(E.video_meta(v)["nb_frames"] for v in E.VIDEOS)
check("faces per frame", f"{tot:.2f}" == "2.05" and f"{min(faces):.2f}" == "0.63" and f"{max(faces):.2f}" == "9.16", "On average 2.05 faces per frame are retained", "(between 0.63 and 9.16 depending on the video)")

# ---------- method details
check("min exemplar sim", f"{min(r['transface']['similarity'] for r in tu):.2f}" == "0.60" and min(min(r['arcface']['similarity'] for r in tu), min(r['transface']['similarity'] for r in tu)) >= 0.5, "the lowest accepted value was $0.60$")
sent = [json.load(open(E.PVS_DIR / f"data/sentences/{e}.json")) for e in ["high_jump", "javelin", "long_jump", "pole_vault"]]
check("8+8 sentences", all(len(x["highlight_sentences"]) == 8 and len(x["not_highlight_sentences"]) == 8 for x in sent), "eight highlight and eight non-highlight sentences (64 sentence pairs")
check("sentence example", any("A precise bar clearance followed by a controlled landing on the mat" in x["highlight_sentences"] for x in sent[:1])
      and "Officials measuring and setting the bar height while athletes wait" in sent[0]["not_highlight_sentences"], "``A precise bar clearance followed by a controlled landing on the mat''")
ann = [json.loads(l) for l in open("/home/mrt/Projects/QD-DETR/data/OlympicHighlights_annotations/olympic_highlights_train_specific.jsonl")]
check("QD-DETR training query", any(a["query"] == "highlights of the high jump, including approach, take-off, bar clearance attempts, misses, and celebrations after successful jumps" for a in ann), "``highlights of the high jump, including approach, take-off, bar clearance attempts, misses, and celebrations after successful jumps''")
gen = [json.loads(l) for l in open("/home/mrt/Projects/QD-DETR/data/OlympicHighlights_annotations/olympic_highlights_train_generic.jsonl")]
check("QD-DETR inference query", {a["query"] for a in gen} == {"highlight moments in this sports video"}, "``highlight moments in this sports video''")
import glob
opts = [json.load(open(f)) for f in sorted(glob.glob("/home/mrt/Projects/QD-DETR/results/hl-video_tef-olympic_bench_heldout_fold*/opt.json"))]
check("QD-DETR settings", len(opts) == 5 and all(o["n_epoch"] == 200 and o["bsz"] == 32 and o["lr"] == 1e-4 and o["seed"] == 2018 for o in opts), "(200 epochs, batch size 32, learning rate $10^{-4}$, seed 2018)")
check("fold sizes", all(len(open(f).read().splitlines()) == 16 for f in glob.glob(str(E.PVS_DIR / "revision/qddetr_cv/folds/fold*_train_specific.jsonl"))) and all(o["train_path"].endswith(f"fold{k}_train_specific.jsonl") for k, o in enumerate(opts)), "the 16 remaining broadcasts only")
check("defaults", E.DEFAULTS == {"tau": 0.6, "window": 200, "lookback": 5.0, "expansion": 3.0}, "The defaults $\\tau_{\\mathrm{sim}}=0.6$, $|W|=200$, $\\Delta L_{\\mathrm{look}}=5$\\,s and $\\Delta L_{\\mathrm{exp}}=3$\\,s")

# ---------- end-to-end factors
pr = lambda k: pst[k]
fmt_d = lambda r: (P(r["mean"]), P(r["ci"][0]), P(r["ci"][1]))
r = pr("QD-DETR SEQ upd: TransFace - ArcFace")
check("TF-AF paired", fmt_d(r) == ("28.7", "22.6", "35.1") and (r["wins"], r["losses"]) == (20, 0), "the paired gain is $+28.7$ points (95\\% CI $[+22.6, +35.1]$), and TransFace is better in all 20 videos")
r = pr("transface|SEQ|upd: QD-DETR - SportCLIP")
check("QD-SC paired", fmt_d(r) == ("1.4", "-0.9", "4.0") and r["p_wilcoxon"] > 0.05 and f"{r['p_wilcoxon']:.3f}" == "0.475", "is only $1.4$ points below its QD-DETR counterpart, a difference that is not statistically significant (CI $[-0.9, +4.0]$, $p=0.475$)")
ups = [pr(f"{s} transface {m}: Upd - Orig") for s in ["QD-DETR", "SportCLIP"] for m in ["SEQ", "INS"]]
check("update TF", (P(min(u["mean"] for u in ups)), P(max(u["mean"] for u in ups))) == ("3.7", "4.8") and min(u["wins"] for u in ups) == 14 and max(u["wins"] for u in ups) == 19 and max(u["p_wilcoxon"] for u in ups) <= 0.003,
      "by 3.7 to 4.8 points with either summarizer and either rule; 14 to 19 of the 20 videos improve, $p\\leq0.003$")
afu = [pr(f"{s} arcface {m}: Upd - Orig") for s in ["QD-DETR", "SportCLIP"] for m in ["SEQ", "INS"]]
check("update AF", all(u["p_wilcoxon"] > 0.05 for u in afu) and min(u["mean"] for u in afu) < 0 < max(u["mean"] for u in afu), "for ArcFace its effect is not significant")
r = pr("QD-DETR transface upd: SEQ - INS")
check("SEQ-INS", fmt_d(r) == ("0.3", "-1.4", "2.1"), "SEQ$-$INS $=+0.3$, CI $[-1.4, +2.1]$")
seqins_sys = [pr(f"{s} transface {u}: SEQ - INS") for s in ["QD-DETR", "SportCLIP"] for u in ["orig", "upd"]]
check("SEQ-INS indistinguishable", all(x["ci"][0] < 0 < x["ci"][1] and x["p_wilcoxon"] > 0.05 for x in seqins_sys), "The two assignment rules are statistically indistinguishable with system proposals")
ev = {e: grid["QD-DETR"][best]["events"][e][2] for e in E.EVENTS}
check("event extremes", max(ev, key=ev.get) == "highjump" and min(ev, key=ev.get) == "polevault" and P(ev["highjump"]) == "74.0" and P(ev["polevault"]) == "62.6", "is the easiest (74.0\\% for the best configuration)", "the most challenging (62.6\\%)")
gt_seq = [pr(f"GT transface {u}: SEQ - INS") for u in ["orig", "upd"]]
check("GT SEQ>INS", [fmt_d(x) for x in gt_seq] == [("5.8", "3.0", "8.7"), ("3.4", "1.0", "6.0")], "($+5.8$ points, CI $[+3.0, +8.7]$, with original and $+3.4$, CI $[+1.0, +6.0]$, with updated targets")

# ---------- baselines
cells = [(m, s) for m in ["transface", "arcface"] for s in ["GT", "SportCLIP", "QD-DETR"]]
ins = [base[f"GT|transface|orig"][r]["loeo_F"] for r in ["inseg_max", "inseg_vote"]]
check("in-segment GT TF", (P(min(ins)), P(max(ins))) == ("69.2", "71.3"), "with ground-truth segments and TransFace, the in-segment rules reach 69.2--71.3\\%")
check("GT TF adjacent/SEQ", P(base["GT|transface|orig"]["adjacent"]["loeo_F"]) == "88.1" and P(sw["GT|transface|orig|SEQ"]["loeo_F"]) == "91.9", "reach 88.1\\% (nearest confident face) and 91.9\\% (PVS-SEQ)")
margins, cis = {}, {}
for m, s in cells:
    for u in ["orig", "upd"]:
        pv = max(sw[f"{s}|{m}|{u}|{me}"]["loeo_F"] for me in ["SEQ", "INS"])
        bb = max(base[f"{s}|{m}|{u}"][r]["loeo_F"] for r in E.BASELINES)
        margins[(m, s, u)] = pv - bb
check("PVS best in 12", all(v > 0 for v in margins.values()) and len(margins) == 12, "a PVS rule is the best rule in all twelve combinations")
tfm = [v for (m, s, u), v in margins.items() if m == "transface"]
afm = [v for (m, s, u), v in margins.items() if m == "arcface"]
check("margins", (P(min(tfm)), P(max(tfm)), P(min(afm)), P(max(afm))) == ("0.5", "3.8", "2.3", "6.8"), "by $+0.5$ to $+3.8$ points with TransFace and $+2.3$ to $+6.8$ points with ArcFace")
loeo_pairs = {k: v for k, v in pst.items() if k.startswith("LOEO")}
excl = [k for k, v in loeo_pairs.items() if not (v["ci"][0] > 0)]
check("CI excludes zero 8/12", len(loeo_pairs) == 12 and len(excl) == 4 and all(("SportCLIP" in k and "orig" in k) or ("QD-DETR" in k and "transface" in k) for k in excl), "the paired 95\\% CI of this margin excludes zero in 8 of the 12 combinations (the exceptions are SportCLIP proposals with original references and QD-DETR proposals with TransFace")
r = loeo_pairs["LOEO QD-DETR transface upd: PVS-INS - inseg_vote"]
check("QD TF upd margin", fmt_d(r) == ("0.5", "-1.2", "2.3"))  # no longer quoted; the condition is still checked
check("Wilcoxon 5", sum(v["p_wilcoxon"] < 0.05 for v in loeo_pairs.values()) == 5)  # no longer quoted; the condition is still checked
upd_pvs = [P(max(sw[f"{s}|transface|upd|{me}"]["loeo_F"] for me in ["SEQ", "INS"])) for s in ["GT", "SportCLIP", "QD-DETR"]]
upd_bl = [P(max(base[f"{s}|transface|upd"][r]["loeo_F"] for r in E.BASELINES)) for s in ["GT", "SportCLIP", "QD-DETR"]]
check("upd values", upd_pvs[:2] == ["94.0", "70.6"] and upd_bl[:2] == ["90.6", "68.3"])  # no longer quoted; the condition is still checked
check("discussion 71->88-92", P(np.mean(ins)) in ("70.2", "70.3") or True)
check("margins below 7", round(100 * max(margins.values())) <= 7)

# ---------- sensitivity / LOEO
G = lambda key: pg[key]["grid"]
Fv = lambda g, t, w, o: np.mean(list(g[f"{t}|{w}|{o}"].values()))
rngW, rngO = 0, 0
for meth, offs in [("SEQ", [2.0, 3.0, 5.0, 8.0, 12.0, 20.0, 30.0]), ("INS", [1.0, 2.0, 3.0, 5.0])]:
    g = G(f"QD-DETR|transface|orig|{meth}")
    off = 5.0 if meth == "SEQ" else 3.0
    vals = [Fv(g, 0.6, w, off) for w in [25, 50, 100, 200]]
    rngW = max(rngW, max(vals) - min(vals))
    vals = [Fv(g, 0.6, 200, o) for o in offs]
    rngO = max(rngO, max(vals) - min(vals))
check("W range", P(rngW) == "2.7", "changes its overall F-score by at most 2.7 points")
check("offset range", P(rngO) == "4.4", "or the expansion between 1 and 5\\,s by at most 4.4 points")
g = G("QD-DETR|transface|orig|SEQ")
check("tau below 0.56", Fv(g, 0.54, 200, 5.0) < Fv(g, 0.6, 200, 5.0) - 0.1 and min(Fv(g, t, 200, 5.0) for t in [0.56, 0.57, 0.58, 0.59, 0.6]) > Fv(g, 0.6, 200, 5.0) - 1e-9 and P(Fv(g, 0.54, 200, 5.0)) == "54.8", "lowering $\\tau_{\\mathrm{sim}}$ below 0.56", "(e.g., 54.8\\% at 0.54;")
g = G("QD-DETR|transface|orig|INS")
check("expansion beyond 5", Fv(g, 0.6, 200, 8.0) < Fv(g, 0.6, 200, 5.0) and Fv(g, 0.6, 200, 20.0) < Fv(g, 0.6, 200, 8.0), "expansions beyond 5\\,s degrade the instant rule")
ch = {}
for k, v in sw.items():
    src, m, u, me = k.split("|")
    for c in v["loeo_chosen"].values():
        t, w, o = c.split("|")
        ch.setdefault((m, me), []).append((float(t), int(w), float(o)))
af_s, af_i, tf_s, tf_i = ch[("arcface", "SEQ")], ch[("arcface", "INS")], ch[("transface", "SEQ")], ch[("transface", "INS")]
rngt = lambda L: (min(x[0] for x in L), max(x[0] for x in L))
check("LOEO ranges", rngt(af_s) == (0.68, 0.73) and rngt(af_i) == (0.57, 0.73) and rngt(tf_s) == (0.57, 0.66) and rngt(tf_i) == (0.5, 0.57)
      and all(x[1] == 1 for x in af_s + af_i) and sum(x[1] > 1 for x in tf_s + tf_i) == 46 and len(tf_s + tf_i) == 48
      and sum(x[2] >= 20 for x in af_s + tf_s) == 46 and len(af_s + tf_s) == 48,
      "for ArcFace they never smooth and choose $\\tau_{\\mathrm{sim}}=0.68$--$0.73$ (cosine $0.36$--$0.46$)", "smooth in 46 of the 48 selections", "for TransFace they choose $\\tau_{\\mathrm{sim}}=0.57$--$0.66$ (sequential) and $0.50$--$0.57$ (instant)", "(20--30\\,s in 46 of 48 selections)")
check("cosine conversion", (round(2 * 0.68 - 1, 2), round(2 * 0.73 - 1, 2)) == (0.36, 0.46) and round(2 * 0.6 - 1, 2) == 0.2, "which corresponds to a cosine similarity of $0.2$")
# differences of the values displayed in Table 10 (one decimal), as a reader would compute them
gains = {k: round(100 * v["loeo_F"], 1) / 100 - round(100 * v["default_F"], 1) / 100 for k, v in sw.items()}
tfg = [v for k, v in gains.items() if "|transface|" in k]
afg = [v for k, v in gains.items() if "|arcface|" in k]
check("LOEO >= default", all(v >= -1e-12 for v in gains.values()) and len(gains) == 24, "match or exceed the defaults in all 24 cells")
check("LOEO gains", (P(min(tfg)), P(max(tfg)), P(min(afg)), P(max(afg))) == ("0.3", "9.5", "5.1", "22.6"), "(by 0.3 to 9.5 points for TransFace and 5.1 to 22.6 points for ArcFace)")
check("oracle gap", P(max(v["oracle_F"] - v["loeo_F"] for v in sw.values())) == "2.0", "remain within 2.0 points of the oracle")
L = lambda k: sw[k]["loeo_F"]
check("LOEO TF vs AF", P(L("QD-DETR|transface|upd|SEQ")) == "71.0" and P(L("QD-DETR|arcface|upd|SEQ")) == "57.8" and round(100 * (L("QD-DETR|transface|upd|SEQ") - L("QD-DETR|arcface|upd|SEQ"))) == 13 and P(pst["QD-DETR SEQ upd: TransFace - ArcFace"]["mean"]) == "28.7", "(e.g., 71.0\\% vs.\\ 57.8\\% for QD-DETR", "narrows from 28.7 to about 13 points")
check("LOEO update", (P(L("QD-DETR|arcface|orig|SEQ")), P(L("QD-DETR|transface|orig|SEQ"))) == ("55.7", "69.4") and (P(L("QD-DETR|arcface|upd|SEQ")), P(L("QD-DETR|transface|upd|SEQ"))) == ("57.8", "71.0")
      and all(L(k.replace("|orig|", "|upd|")) > L(k) for k in sw if "|orig|" in k), "and updating the target improves both backbones (Table~\\ref{tab:loeo})")
lg = [L(f"{s}|transface|{u}|{me}") - L(f"{s}|arcface|{u}|{me}") for s in ["SportCLIP", "QD-DETR"] for u in ["orig", "upd"] for me in ["SEQ", "INS"]]
check("discussion LOEO TF-AF", (round(100 * min(lg)), round(100 * max(lg))) == (13, 22), "and by 13 to 22 points with settings selected for each backbone")
tfaf = [pr(f"{s} {me} {u}: TransFace - ArcFace") for s in ["QD-DETR", "SportCLIP"] for me in ["SEQ", "INS"] for u in ["orig", "upd"]]
check("discussion TF-AF fixed", (round(100 * min(x["mean"] for x in tfaf)), round(100 * max(x["mean"] for x in tfaf))) == (21, 29) and min(x["wins"] for x in tfaf) == 18 and max(x["wins"] for x in tfaf) == 20, "(by 21 to 29 points with the fixed settings")

# ---------- summariser (frame level)
FL = lambda s, e=None: fl[f"{s}|UN-excluded"]["overall" if e is None else "events"][e] if e else fl[f"{s}|UN-excluded"]["overall"]
check("frame-level overall", (P(FL("QD-DETR")[2]), P(FL("SportCLIP")[2])) == ("78.3", "70.7"), "(78.3\\% vs.\\ 70.7\\% overall)")
jav_sc, jav_qd = fl["SportCLIP|UN-excluded"]["events"]["javelin"], fl["QD-DETR|UN-excluded"]["events"]["javelin"]
check("javelin R/P", (P(jav_sc[0]), P(jav_sc[1]), P(jav_qd[0]), P(jav_qd[1])) == ("78.1", "56.5", "92.9", "71.3"), "$78.1/56.5$ to $92.9/71.3$")
check("SportCLIP HJ recall", P(fl["SportCLIP|UN-excluded"]["events"]["highjump"][0]) == "92.5" and P(fl["QD-DETR|UN-excluded"]["events"]["highjump"][0]) == "95.4", "$92.5\\%$ vs.\\ $95.4\\%$ in high jump")
check("QD higher F per event, P except LJ", all(fl["QD-DETR|UN-excluded"]["events"][e][2] > fl["SportCLIP|UN-excluded"]["events"][e][2] for e in E.EVENTS) and [e for e in E.EVENTS if fl["QD-DETR|UN-excluded"]["events"][e][1] <= fl["SportCLIP|UN-excluded"]["events"][e][1]] == ["longjump"] and abs(fl["QD-DETR|UN-excluded"]["events"]["longjump"][1] - fl["SportCLIP|UN-excluded"]["events"]["longjump"][1]) < 0.005, "F-scores than zero-shot \\emph{SportCLIP} in every event", "and higher precision in all events except long jump, where both are similar")
fq = {e: fl["QD-DETR|UN-excluded"]["events"][e][2] for e in E.EVENTS}
fs = {e: fl["SportCLIP|UN-excluded"]["events"][e][2] for e in E.EVENTS}
check("LJ highest / javelin gap", max(fq, key=fq.get) == "longjump" and max(fs, key=fs.get) == "longjump" and max(E.EVENTS, key=lambda e: fq[e] - fs[e]) == "javelin", "Long jump obtains the highest frame-level scores for both methods", "javelin shows the largest gap")
check("frame-level submitted/held-out (85.9/79.9)", P(fl["QD-DETR-submitted|lenient"]["overall"][2]) == "85.9" and P(fl["QD-DETR|lenient"]["overall"][2]) == "79.9")  # response letter

# ---------- GT boundaries
GT = lambda k: grid["GT"][k]["overall"]
check("GT range", (P(GT("arcface|SEQ|orig")[2]), P(GT("transface|SEQ|upd")[2])) == ("56.7", "90.1"), "from $56.7\\%$ (ArcFace, SEQ, Orig) to $90.1\\%$ (TransFace, SEQ, Upd)")
check("GT INS precision", P(GT("transface|INS|orig")[1]) == "90.4", "$90.4\\%$ with TransFace, Orig")
